import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Troubleshooting: BcContainerHelper Module Loading Errors","description":"","frontmatter":{},"headers":[],"relativePath":"installation-and-setup/troubleshooting-powershell-errors.md","filePath":"installation-and-setup/troubleshooting-powershell-errors.md"}`),a={name:`installation-and-setup/troubleshooting-powershell-errors.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="troubleshooting-bccontainerhelper-module-loading-errors" tabindex="-1">Troubleshooting: BcContainerHelper Module Loading Errors <a class="header-anchor" href="#troubleshooting-bccontainerhelper-module-loading-errors" aria-label="Permalink to “Troubleshooting: BcContainerHelper Module Loading Errors”">​</a></h1><h2 id="problem" tabindex="-1">Problem <a class="header-anchor" href="#problem" aria-label="Permalink to “Problem”">​</a></h2><p>When running a Business Central setup command such as:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-BcArtifactUrl</span></span></code></pre></div><p>PowerShell returns an error similar to:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Get-BcArtifactUrl : The &#39;Get-BcArtifactUrl&#39; command was found in the</span></span>
<span class="line"><span>module &#39;BcContainerHelper&#39;, but the module could not be loaded.</span></span>
<span class="line"><span>For more information, run &#39;Import-Module BcContainerHelper&#39;.</span></span></code></pre></div><p>Attempting to import the module directly:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Import-Module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BcContainerHelper</span></span></code></pre></div><p>Produces the following error:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Import-Module : File C:\\Program Files\\WindowsPowerShell\\Modules\\BcContainerHelper\\6.1.19\\BcContainerHelper.psm1</span></span>
<span class="line"><span>cannot be loaded because running scripts is disabled on this system.</span></span></code></pre></div><h2 id="cause" tabindex="-1">Cause <a class="header-anchor" href="#cause" aria-label="Permalink to “Cause”">​</a></h2><p>PowerShell&#39;s execution policy prevents the <code>BcContainerHelper</code> module from loading.</p><p>The module is installed, but PowerShell cannot execute its script files because of the current execution policy.</p><p><strong>Important:</strong> This is a PowerShell configuration issue, not necessarily a problem with the module installation.</p><h2 id="solution" tabindex="-1">Solution <a class="header-anchor" href="#solution" aria-label="Permalink to “Solution”">​</a></h2><h3 id="step-1-check-the-current-execution-policy" tabindex="-1">Step 1: Check the current execution policy <a class="header-anchor" href="#step-1-check-the-current-execution-policy" aria-label="Permalink to “Step 1: Check the current execution policy”">​</a></h3><p>Open Windows PowerShell and run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-ExecutionPolicy</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">List</span></span></code></pre></div><p>This displays the execution policies configured at different scopes, including the current user and local machine.</p><h3 id="step-2-update-the-execution-policy-for-the-current-user" tabindex="-1">Step 2: Update the execution policy for the current user <a class="header-anchor" href="#step-2-update-the-execution-policy-for-the-current-user" aria-label="Permalink to “Step 2: Update the execution policy for the current user”">​</a></h3><p>Run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-ExecutionPolicy</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scope CurrentUser </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy RemoteSigned</span></span></code></pre></div><p>If prompted for confirmation, enter <code>Y</code>.</p><p><strong>Why <code>RemoteSigned</code>?</strong></p><p>This policy allows locally created scripts to run without a digital signature. Scripts downloaded from the internet generally require a trusted digital signature unless their downloaded-file mark has been removed.</p><p>Using <code>CurrentUser</code> limits the configuration change to the current Windows user instead of changing the policy for all users on the machine.</p><blockquote><p><strong>Note:</strong> If your organization enforces an execution policy through Group Policy, that policy may override your setting. Follow your organization&#39;s requirements rather than attempting to bypass its restrictions.</p></blockquote><h3 id="step-3-import-bccontainerhelper" tabindex="-1">Step 3: Import BcContainerHelper <a class="header-anchor" href="#step-3-import-bccontainerhelper" aria-label="Permalink to “Step 3: Import BcContainerHelper”">​</a></h3><p>After updating the execution policy, run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Import-Module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BcContainerHelper </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Verbose</span></span></code></pre></div><p>The <code>-Verbose</code> parameter displays additional information about the module-loading process, which can help with troubleshooting.</p><h3 id="step-4-verify-that-the-module-loaded-successfully" tabindex="-1">Step 4: Verify that the module loaded successfully <a class="header-anchor" href="#step-4-verify-that-the-module-loaded-successfully" aria-label="Permalink to “Step 4: Verify that the module loaded successfully”">​</a></h3><p>Run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Command</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Get-BcArtifactUrl</span></span></code></pre></div><p>If the import succeeds, PowerShell should display information about the command, including its source module.</p><p>You can also check the installed module:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BcContainerHelper </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ListAvailable</span></span></code></pre></div><h3 id="step-5-retry-the-original-command" tabindex="-1">Step 5: Retry the original command <a class="header-anchor" href="#step-5-retry-the-original-command" aria-label="Permalink to “Step 5: Retry the original command”">​</a></h3><p>Run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-BcArtifactUrl</span></span></code></pre></div><p>If the module loads correctly, the original module-loading error should no longer occur.</p><h2 id="troubleshooting-checklist" tabindex="-1">Troubleshooting Checklist <a class="header-anchor" href="#troubleshooting-checklist" aria-label="Permalink to “Troubleshooting Checklist”">​</a></h2><p>If the problem persists, verify the following:</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"><code>BcContainerHelper</code> is installed.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> The installed module&#39;s files are present.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> The PowerShell execution policy permits the module&#39;s script files to run.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> The module imports successfully using <code>Import-Module BcContainerHelper</code>.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"><code>Get-Command Get-BcArtifactUrl</code> recognizes the command.</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> No organization-managed execution policy is preventing the change.</label></li></ul><p>To inspect the PowerShell version, run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$PSVersionTable</span></span></code></pre></div><p>To inspect the installed module versions and their locations, run:</p><div class="language-powershell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Module</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> BcContainerHelper </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ListAvailable </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    Select-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Name</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Version</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ModuleBase</span></span></code></pre></div><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p>When PowerShell recognizes a command but cannot load its associated module, do not immediately reinstall the module.</p><p>First, inspect the underlying error. If it indicates that script execution is disabled, investigate the execution policy before changing or reinstalling other components.</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_execution_policies" target="_blank" rel="noreferrer">PowerShell execution policies — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/import-module" target="_blank" rel="noreferrer">Import-Module — Microsoft Learn</a></li><li><a href="https://github.com/microsoft/navcontainerhelper" target="_blank" rel="noreferrer">BcContainerHelper — Official GitHub repository</a></li><li><a href="https://github.com/microsoft/navcontainerhelper/blob/master/Module/BcContainerHelper/Artifacts/Get-BcArtifactUrl.ps1" target="_blank" rel="noreferrer">Get-BcArtifactUrl — BcContainerHelper documentation</a></li></ul>`,53)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};